// ar.js — the Arabic, keyed by the English it replaces. Loaded only in Arabic
// mode (js/i18n.js); English never fetches this file.
//
// Written the way a physics teacher in the Gulf says it to an A-level student,
// in the terms of the school curricula. design/arabic-glossary.md is the word
// list and the symbol table; every entry here keeps to them. In Arabic mode the
// only Latin-looking thing left on screen is a digit.
//
// A key is the English with {0}, {1} slots: a number, a name or an equation goes
// there, wherever the Arabic wants it. Some keys are pieces of a sentence the
// code builds around bold text.

