  "Aimed below the horizontal, so it is falling before it has gone anywhere. No upward half, no greatest height — and a negative angle, which is where the marks go.": "يُصوَّب تحت الأفقي، فيبدأ بالهبوط من اللحظة الأولى. لا نصف صاعد ولا أقصى ارتفاع — والزاوية سالبة، وهنا تضيع الدرجات عادةً.",
