  "It crosses the line twice. The gap between those times is the answer. Drag the line. Thrown straight up works too — the same two crossings, one above the other.": "يعبر الخط مرتين، والفرق بين الزمنين هو الإجابة. اسحب الخط. ويصلح هذا للقذف الرأسي أيضًا — العبوران نفسهما، أحدهما فوق الآخر.",
  "Parachute drop": "القفز بالمظلة",
  "free fall, then the canopy": "سقوط حر، ثم تنفتح المظلة",
  "Three phases, and SUVAT applies to each one separately: free fall under gravity alone, a hard deceleration as the canopy opens, then a steady descent at constant speed. The equations never described the whole fall — only a stretch of it at a time, which is what this one is for.": "ثلاث مراحل، وتُطبَّق معادلات سوفات على كل منها على حدة: سقوط حر تحت تأثير الجاذبية وحدها، ثم تباطؤ شديد حين تنفتح المظلة، ثم هبوط بسرعة ثابتة. المعادلات لا تصف السقوط كله دفعة واحدة — بل جزءًا منه في كل مرة، وهذا ما صُمّم له هذا الموقف.",
  "Three phases, and SUVAT three times over.": "ثلاث مراحل، وسوفات ثلاث مرات.",
  "Dropping vs Firing a Bullet": "إسقاط رصاصة أم إطلاقها؟",
  "which lands first?": "أيهما يصل أولًا؟",
  "Two identical rounds leave the bench at the same instant: one fired flat, one simply released. Vertically they are the same problem — neither starts with any upward speed, and both are pulled down at the same rate — because firing adds velocity sideways only, and the two components are independent. The horizontal push buys no hang time at all, at any muzzle speed.": "رصاصتان متطابقتان تغادران الطاولة في اللحظة نفسها: واحدة تُطلق أفقيًا، والأخرى تُترك فقط. رأسيًا هما المسألة نفسها — لا تبدأ أي منهما بسرعة رأسية، وكلتاهما تُسحب لأسفل بالمعدل نفسه — لأن الإطلاق يضيف سرعة أفقية فقط، والمركّبتان مستقلتان. الدفعة الأفقية لا تطيل زمن البقاء في الهواء أبدًا، مهما كانت سرعة الإطلاق.",
  "Pick a round": "اختر رصاصة",
  "Air rifle": "بندقية هوائية",
  "Pistol": "مسدس",
  "Service rifle": "بندقية عسكرية",
  "Both hit the ground at the same time.": "كلتاهما تصلان إلى الأرض في اللحظة نفسها.",
  "Monkey vs Hunter": "القرد والصياد",
  "aim straight at it": "صوّب نحوه مباشرة",
  "The hunter aims directly AT the monkey; the monkey drops the instant the shot leaves. In the time the banana takes to cover the horizontal gap, both have fallen the same ½gt² below where they would have been without gravity — so the aim that would have been right without gravity is still right with it. Drag the monkey anywhere: it only fails if the monkey reaches the ground first.": "يصوّب الصياد نحو القرد مباشرة، ويُفلت القرد الغصن لحظة الإطلاق. وفي الزمن الذي تقطع فيه الموزة المسافة الأفقية، يكون كلاهما قد هبط المسافة نفسها ½ جـ ز² تحت الموضع الذي كان سيبلغه لولا الجاذبية — فالتصويب الذي يصيب دون جاذبية يصيب معها أيضًا. اسحب القرد إلى أي مكان: لا يخطئ إلا إذا بلغ القرد الأرض أولًا.",
  "Caught.": "أصابه.",
  "It passed above the monkey.": "مرّت فوق القرد.",
  "It passed below the monkey.": "مرّت تحت القرد.",
  "The monkey reached the ground first.": "بلغ القرد الأرض أولًا.",
  "Aim at the monkey": "صوّب نحو القرد",
  "Aimed at the monkey, so it follows wherever the monkey hangs — below the horizontal included.": "التصويب نحو القرد، فيتبعه أينما تعلّق — حتى تحت الأفقي.",
  "A tree, a throw, and nothing else in the way": "شجرة، ورمية، ولا شيء آخر في الطريق",
