  "A vehicle passes A, and some time later passes B. Its acceleration is its own, so a is one of the five like the rest — and the area under the velocity–time line is the distance AB.": "مركبة تمر بالنقطة أ، وبعد مدة تمر بالنقطة ب. تسارعها خاص بها، فيكون ت أحد المتغيرات الخمسة كغيره — والمساحة تحت خط السرعة–الزمن هي المسافة أب.",
  "Past-paper library": "مكتبة أسئلة الامتحانات",
  "Scenarios built for real exam questions — AQA, Edexcel, OCR, CIE — each naming its papers.": "مواقف مبنية على أسئلة امتحانات حقيقية — إيه كيو إيه وإدكسل وأو سي آر وسي آي إي — وكل موقف يذكر أوراقه.",
