  "time in s": "الزمن بالثانية",
  "The motion is already determined, so the remaining {n} boxes are closed — anything typed there could only repeat or contradict what is here.": "الحركة محددة بالكامل، لذا أُغلقت الخانات {n} الباقية — فأي شيء يُكتب فيها إما أن يكرر ما هنا أو يناقضه.",
