  "None 0": "بلا جاذبية 0",
  "Earth": "الأرض",
  "Moon": "القمر",
  "None": "بلا جاذبية",
  "Everything needed is here.": "كل ما يلزم موجود.",
  "s is measured horizontally from the launch. u and v are speeds.": "تُقاس ف أفقيًا من نقطة القذف. و ع₀ و ع سرعتان.",
  "The launch height was more than enough — the rest already fixed the motion, and it agrees with them.": "ارتفاع نقطة القذف زائد عن الحاجة — فالقيم الأخرى حدّدت الحركة، وهو متّفق معها.",
  "Launch at {v} m s⁻¹": "انطلق بسرعة {v} م/ث",
  "Not recommended — slower than this flight wants: {a} s on screen rather than {b} s.": "غير مستحسن — أبطأ مما تحتاجه هذه الحركة: {a} ث على الشاشة بدل {b} ث.",
  "Not recommended — too fast to follow. The whole flight would be over in {a} s, against {b} s at the speed it asked for.": "غير مستحسن — أسرع من أن تتابعه العين. ستنتهي الحركة كلها في {a} ث، مقابل {b} ث بالسرعة المطلوبة.",
  "Not recommended — far slower than it needs to be. You would be watching for {a} s, against {b} s at the speed it asked for.": "غير مستحسن — أبطأ بكثير من اللازم. ستشاهد لمدة {a} ث، مقابل {b} ث بالسرعة المطلوبة.",
  "About {a} s on screen, for a flight that really lasts {b} s.": "نحو {a} ث على الشاشة، لحركة تستغرق فعلًا {b} ث.",
  "Set up": "الإعداد",
  "How is the jump set up?": "كيف تُجهَّز القفزة؟",
  "Four numbers, and none of them is one of the five. The fall is in three phases and the five equations are applied to": "أربعة أرقام، وليس أي منها من المتغيرات الخمسة. السقوط على ثلاث مراحل، وتُطبَّق المعادلات الخمس على",
  "each phase in turn": "كل مرحلة بدورها",
  "— which is the whole reason this question gets set.": "— وهذا هو سبب طرح هذا السؤال أصلًا.",
  "Height she jumps from h (m)": "الارتفاع الذي تقفز منه ل (م)",
  "A display team leaves the aircraft far higher than anything that fits on one screen; a hundred metres or so shows the whole descent at once.": "فرق الاستعراض تقفز من ارتفاع أكبر بكثير مما تتسع له شاشة واحدة؛ ونحو مئة متر تكفي لعرض الهبوط كله دفعة واحدة.",
  "Free fall before the canopy opens (s)": "السقوط الحر قبل انفتاح المظلة (ث)",
  "Long enough that she is really moving. From a hundred metres there are about four and a half seconds of fall to spend.": "مدة كافية لتكتسب سرعة حقيقية. من ارتفاع مئة متر يتوفر نحو أربع ثوانٍ ونصف من السقوط.",
  "Deceleration once it is open (m s⁻²)": "التباطؤ بعد انفتاحها (م/ث²)",
  "An opening is violent — somewhere around 20 to 30 m s⁻², which is two or three times g, upwards.": "انفتاح المظلة عنيف — في حدود 20 إلى 30 م/ث²، أي ضعفي جـ أو ثلاثة أضعافها، نحو الأعلى.",
  "Steady speed under the canopy (m s⁻¹)": "السرعة الثابتة تحت المظلة (م/ث)",
  "About 5 to 7 m s⁻¹ under a sport canopy: the speed you land at stepping off a two-metre wall.": "نحو 5 إلى 7 م/ث تحت مظلة رياضية: السرعة التي تهبط بها لو نزلت عن جدار ارتفاعه مترَان.",
  "The free fall is the only phase this governs. The other two are set by the canopy, and the engine uses the figures you gave for them.": "هذا يتحكم في مرحلة السقوط الحر وحدها. أما المرحلتان الأخريان فتحدّدهما المظلة، ويستخدم المحرّك الأرقام التي أعطيتها لهما.",
  "Ready. The rest comes out as:": "جاهز. والباقي يخرج هكذا:",
  "Taking downwards as positive, and timing each phase from its own start.": "نأخذ الاتجاه لأسفل موجبًا، ونقيس زمن كل مرحلة من بدايتها.",
  "Each phase is solved on its own, and the five equations are applied to it three times over — they describe a stretch of constant acceleration, which is what each phase is and what the whole descent is not.": "تُحلّ كل مرحلة وحدها، فتُطبَّق المعادلات الخمس ثلاث مرات — لأنها تصف مقطعًا بتسارع ثابت، وهذا حال كل مرحلة، لا حال الهبوط كله.",
  "Jump": "اقفز",
  "The jump": "القفزة",
  "The aircraft, the door and the aircraft’s own way down after the drop are all scenery. She leaves from rest and falls straight down; the model has no sideways motion in it at all.": "الطائرة وبابها ومسارها بعد القفز كلها ديكور. تبدأ المظلّية من السكون وتسقط رأسيًا؛ لا حركة أفقية في النموذج إطلاقًا.",
  "What is moving": "ما الذي يتحرك",
