  "Runner": "عدّاء",
  "Whatever the question names. The physics is the same for all of them; the stage draws that one.": "أيًّا كان ما يذكره السؤال. الفيزياء واحدة لها جميعًا؛ والمشهد يرسم ما تختاره.",
  "Any three of the five give you the other two. Here": "أي ثلاث من الخمس تعطيك الاثنتين الباقيتين. هنا",
  "is the vehicle’s own acceleration, not g — and towards A is negative, so braking on the way to B is a negative one.": "هو تسارع المركبة نفسها، لا جـ — والاتجاه نحو أ سالب، فالكبح في الطريق إلى ب تسارع سالب.",
  "A point to time it at, from A (m)": "نقطة نحسب الزمن عندها، من أ (م)",
