  "Steepest in free fall, a knee where the canopy opens, then a straight ramp down at constant speed.": "أشد انحدارًا في السقوط الحر، ثم انعطاف حين تنفتح المظلة، ثم خط مستقيم هابط بسرعة ثابتة.",
  "A step, not a number. Gravity alone, then the canopy pulling back harder than gravity pulls down, then nothing at all.": "قفزات لا رقم واحد: الجاذبية وحدها، ثم المظلة تشدّ لأعلى أقوى مما تشدّ الجاذبية لأسفل، ثم لا شيء إطلاقًا.",
