  "You are offline. Scenarios still work; Ask Suvat will wait for the connection.": "أنت غير متصل بالإنترنت. المواقف تعمل كالمعتاد، أما اسأل سوفات فينتظر عودة الاتصال.",
  "warn": "تنبيه",
  "Back online.": "عاد الاتصال.",
  "Something went wrong drawing that. Try again, or reload if it sticks.": "حدث خطأ أثناء الرسم. حاول مرة أخرى، أو أعد تحميل الصفحة إن استمر.",
  "Signing in did not work. Try again.": "لم ينجح تسجيل الدخول. حاول مرة أخرى.",
  "Signing in was cancelled.": "أُلغي تسجيل الدخول.",
  "That sign-in link has expired or was used already. Ask for a new one.": "انتهت صلاحية رابط الدخول أو استُخدم من قبل. اطلب رابطًا جديدًا.",
  "failed": "فشل",
