  "{0}’s own acceleration, not g — and towards A is negative, so {1} on the way to B is a negative one.": "تسارع {0} نفسه، وليس جـ. والاتجاه نحو أ سالب، فيكون {1} في الطريق إلى ب سالبًا.",
  "Four numbers, and none of them is one of the five. The fall is in three": "أربعة أعداد، وليس بينها أي من الخمسة. السقوط على ثلاث",
  "phases and the five equations are applied to": "مراحل، وتُطبَّق المعادلات الخمس على",
