  "A display team leaves the aircraft far higher than anything that fits on": "يقفز فريق الاستعراض من ارتفاع أعلى بكثير مما تتسع له",
  "one screen; a hundred metres or so shows the whole descent at once.": "شاشة واحدة؛ ومئة متر تقريبًا تُظهر الهبوط كله دفعة واحدة.",
