  "Straight-line motion.": "حركة في خط مستقيم.",
  "No angle was given and none can be worked out from these values — so the engine is solving the five along one line, which is the correct answer to a question that never mentioned a direction. Nothing is missing. Add the angle, or give where it lands, if you want the arc drawn.": "لم تُعطَ زاوية ولا يمكن استنتاجها من هذه القيم، لذا يحل المحرّك المعادلات الخمس على خط واحد، وهذا هو الحل الصحيح لسؤال لم يذكر اتجاهًا أصلًا. لا شيء ناقص. أضف الزاوية، أو أعطِ مكان الهبوط، إن أردت رسم القوس.",
  "at the angle you gave, {0}°.": "بالزاوية التي أعطيتها، {0}°.",
  "A two-dimensional arc.": "قوس في بعدين.",
  "You did not give the angle and did not need to — the engine recovered it as {0}°.": "لم تعطِ الزاوية ولم تكن بحاجة إلى ذلك: فقد استنتجها المحرّك {0}°.",
  "at {0}°.": "بزاوية {0}°.",
  "Worked out, not needed.": "محسوبة، ولا حاجة إلى إدخالها.",
  "The engine had everything it needed without it — {0}. Leaving this box blank is a normal thing to do, and usually the right one.": "كان لدى المحرّك كل ما يحتاج إليه من دونها: {0}. ترك هذه الخانة فارغة أمر عادي، وهو الصواب غالبًا.",
  "Leave it blank.": "اتركها فارغة.",
  "The five equations never mention an angle, so one is only wanted here to draw an arc. Without it the motion is solved along a line and every number is still exact.": "المعادلات الخمس لا تذكر زاوية أبدًا، فالزاوية مطلوبة هنا لرسم القوس فقط. ومن دونها تُحل الحركة على خط واحد وتبقى كل الأعداد دقيقة.",
  "There are two.": "هناك زاويتان.",
  "{0}° and {1}° both land in the same place — the low ball and the high ball. This is the shallower.": "{0}° و{1}° تهبطان في المكان نفسه: الكرة المنخفضة والكرة العالية. وهذه هي الأقل ميلًا.",
  "Use {2}° instead": "استخدم {2}° بدلًا منها",
  "Extra values are allowed. The engine will still refuse ones that contradict.": "القيم الإضافية مسموحة، لكن المحرّك يرفض ما يتناقض منها.",
  "Guard them": "احمِها",
