  "The motion is already determined, so the {0} closed — anything typed there could only repeat or contradict what is here.": "الحركة محددة بالفعل، لذا أُغلقت {0}: فأي شيء يُكتب فيها لن يكون إلا تكرارًا لما هنا أو تناقضًا معه.",
  "This flight has no bounce to shape — it either never lands or has stopped moving by the time it does.": "لا ارتداد في هذه الحركة لتعديله: فهي إما لا تهبط أبدًا وإما تكون قد توقفت عند هبوطها.",
