  "Shown to two places. Working with {0}°, exactly as typed.": "معروضة بمنزلتين عشريتين، والحساب يجري على {0}° كما كُتبت تمامًا.",
  "That is not a height. Try a number, or a fraction like 7/2.": "هذا ليس ارتفاعًا. جرّب عددًا، أو كسرًا مثل 7/2.",
  "Fill in enough of the five first — there is no flight to put a line across yet.": "املأ ما يكفي من الخمسة أولًا: فلا توجد حركة بعد ليُمد خط عبرها.",
  "That is not a time. Try a number, or a fraction like 7/2.": "هذا ليس زمنًا. جرّب عددًا، أو كسرًا مثل 7/2.",
  "A line at {0} m gives exactly that.": "خط عند {0} م يعطي ذلك بالضبط.",
  "That is its greatest height: it just reaches it, at {0}, and is never above it.": "هذا أقصى ارتفاع له: يبلغه بالكاد عند {0}، ولا يتجاوزه أبدًا.",
