  "It starts on it and rises away from it: with no gravity it never comes back down.": "يبدأ عليه ويرتفع مبتعدًا عنه: فمن دون جاذبية لا يعود إلى أسفل أبدًا.",
  "It starts on it and, with no gravity, keeps level with it.": "يبدأ عليه، ومن دون جاذبية يبقى في مستواه.",
  "With no gravity it never comes back down: it stays above it.": "من دون جاذبية لا يعود إلى أسفل أبدًا: يبقى فوقه.",
  "It passes it at {0} going up and {1} coming down, so it is above it for {2}.": "يمر به عند {0} صاعدًا وعند {1} نازلًا، فيبقى فوقه مدة {2}.",
  "It starts on it and comes back down to it when it lands, at {0}.": "يبدأ عليه ويعود إليه عند الهبوط، عند {0}.",
