  "Downwards is positive. {11} and {12} in {13}, {14} in {15}, {16} in {17}, {18} in {19} — and each {20} is timed from the start of its own phase.": "الاتجاه إلى أسفل موجب. {11} و{12} بوحدة {13}، و{14} بوحدة {15}، و{16} بوحدة {17}، و{18} بوحدة {19}. وكل {20} يُحسب من بداية مرحلته.",
  "The canopy never finished its job: there was not enough height left to bring her from {0} m s⁻¹ down to the {1} m s⁻¹ you asked for, so she arrived at": "لم تُكمل المظلة مهمتها: لم يبقَ ارتفاع كافٍ لخفض سرعتها من {0} م/ث إلى {1} م/ث التي طلبتها، فوصلت بسرعة",
  "instead — still decelerating. The row below the free fall is cut short for that reason, and there is no third row at all.": "بدلًا من ذلك، وهي لا تزال تتباطأ. لهذا جاء الصف الذي يلي السقوط الحر مبتورًا، ولا يوجد صف ثالث أصلًا.",
  "No single row of five describes this fall, and that is the whole point of the question. Each phase has its own constant acceleration, so each one is a separate SUVAT problem — and the only thing they share is that the {0} of one is the {1} of the next.": "لا يصف هذا السقوط صف واحد من خمس قيم، وهذا هو جوهر السؤال. لكل مرحلة تسارعها الثابت، فكل منها مسألة سوفات مستقلة، ولا يجمع بينها إلا أن {0} في إحداها هي {1} في التي تليها.",
  "Speed against time: it rises in free fall, drops sharply as the canopy opens, then stays level.": "السرعة مقابل الزمن: ترتفع في السقوط الحر، وتنخفض بحدة عند فتح المظلة، ثم تثبت.",
  "Speed against time, in {23} — straight lines, because the acceleration is constant inside each phase. The shaded area is how far she fell: {24}.": "السرعة مقابل الزمن، بوحدة {23}: خطوط مستقيمة لأن التسارع ثابت داخل كل مرحلة. والمساحة المظللة هي المسافة التي سقطتها: {24}.",
  "Aimed straight at the monkey": "مصوَّبة نحو القرد مباشرة",
