  ". In that time both of them fell": ". وخلال ذلك الزمن سقط كلاهما",
  "below where they would have been with no gravity at all — the same {3}, for both, which is why the two cancel and the aim survives.": "تحت الموضع الذي كانا سيبلغانه لولا الجاذبية: {3} نفسها لكليهما، ولهذا يلغي أحدهما الآخر ويبقى التصويب صحيحًا.",
