  "by then — the shared fall was never the problem. The aim was {4}° {5} the line to the monkey, and that is exactly what it missed by.": "نفسها حتى ذلك الحين، فالسقوط المشترك لم يكن المشكلة قط. كان التصويب {4}° {5} الخط الواصل إلى القرد، وهذا بالضبط مقدار ما أخطأ به.",
