  "Across from the start": "أفقيًا من البداية",
  "Across from where it was let go": "أفقيًا من نقطة تركه",
  "Out from the {0}": "بعيدًا عن {0}",
  "From {0}": "من {0}",
  "Composed by Ask Suvat: {0}, {1}, {2}.": "ركّبه اسأل سوفات: {0}، {1}، {2}.",
  "Side on: {0}, and {1}": "من الجانب: {0}، و{1}",
  "See the scene": "شاهد المشهد",
  "What the model leaves out": "ما يهمله النموذج",
  "The model the scene is drawn from. None of this was computed; it is what the numbers were taken to mean.": "هذا هو النموذج الذي رُسم منه المشهد. لا شيء هنا محسوب؛ إنما هو ما فُهم من الأعداد.",
  "are particles": "جسيمات",
  "is a particle": "جسيم",
  "it has no size and does not spin or tumble: only g acts on it once it is launched. The drawing turns it to face the way it moves; the engine does not.": "لا حجم له ولا يدور ولا ينقلب: لا يؤثر عليه بعد قذفه إلا جـ. الرسم يديره ليواجه اتجاه حركته، أما المحرّك فلا.",
  "no size, no spin: only g acts on them in the air, and they meet when they are at the same height.": "لا حجم ولا دوران: لا يؤثر عليهما في الهواء إلا جـ، ويلتقيان حين يكونان على الارتفاع نفسه.",
  "no size, no spin: only g acts on it in the air, and it bounces straight back up.": "لا حجم ولا دوران: لا يؤثر عليها في الهواء إلا جـ، وترتد رأسيًا إلى أعلى.",
  "No air resistance": "لا مقاومة للهواء",
  "nothing slows it but gravity, however fast or far it goes.": "لا يبطئه إلا الجاذبية، مهما بلغت سرعته أو مسافته.",
  "An instant bounce": "ارتداد لحظي",
  "the ball is in contact with the ground for no time at all, and keeps the same fraction of its speed every time.": "لا تلامس الكرة الأرض إلا لزمن معدوم، وتحتفظ بالكسر نفسه من سرعتها في كل مرة.",
  "{0} is drawn to the scale of the motion": "{0} مرسوم بمقياس الحركة",
  "the heights and distances on the stage are the engine’s own.": "الارتفاعات والمسافات في المشهد هي نفسها أرقام المحرّك.",
  "What the engine did compute is above, from what you gave: every moment and speed is its own.": "ما حسبه المحرّك فعلًا موجود أعلاه، مما أعطيته: كل لحظة وكل سرعة من حسابه هو.",
  "Drawn as {0} here: {1} does not fit this scene.": "مرسوم هنا في صورة {0}: {1} لا يناسب هذا المشهد.",
  "Drawn as {0}: there is no {1} figure yet.": "مرسوم في صورة {0}: لا يوجد شكل لـ {1} بعد.",
