  "No angle was given for the jump, so it is taken as straight up, {0}, as an exam would take it. Change {1} on the values screen to try another.": "لم تُذكر زاوية للقفزة، فنعدّها رأسية إلى أعلى، {0}، كما يفعل الامتحان. غيّر {1} في شاشة القيم لتجرّب زاوية أخرى.",
  "The {0} is drawn as a table: only its height matters to the motion.": "{0} مرسوم في صورة طاولة: لا يهم للحركة إلا ارتفاعه.",
  "Struck": "ضُرب",
