  "{0} {1} m above the ground, {2}.": "{0} على ارتفاع {1} م فوق الأرض، {2}.",
  "The question names no place, so it is drawn off a wall {0} m high: only the height matters to the motion.": "لا يذكر السؤال مكانًا، فرسمناه من فوق جدار ارتفاعه {0} م: لا يهم للحركة إلا الارتفاع.",
  "No speed was given for the jump, so it is taken as stepping off from rest. Give the speed on the values screen if the question has one.": "لم تُذكر سرعة للقفزة، فنعدّها نزولًا من السكون. اكتب السرعة في شاشة القيم إن كانت في السؤال.",
