  "No height was given, so I’ve used {0} m for {1}. Tell me the real one and I’ll run it again.": "لم يُذكر ارتفاع، فاستخدمتُ {0} م لـ {1}. أخبرني بالارتفاع الحقيقي وسأعيد الحل.",
  "The question gives {0} m, but the speed and the angle already decide where it lands, and it is not {1} m. So I’ve run it from the speed and the angle and left the {2} m out: it is about something else, like where a fielder or a wall is. The working shows where it lands.": "يذكر السؤال {0} م، لكن السرعة والزاوية تحددان وحدهما موضع سقوطه، وهو ليس {1} م. لذلك حللتُه من السرعة والزاوية وتركتُ {2} م جانبًا: فهي تخص شيئًا آخر، كموقع لاعب أو جدار. والحل يبيّن موضع سقوطه.",
  "The question gives {0} s, but the speed and the angle already decide how long it is in the air, and it is not {1} s. So I’ve run it from the speed and the angle and left the {2} s out: it is about something else. The working shows how long it is in the air.": "يذكر السؤال {0} ث، لكن السرعة والزاوية تحددان وحدهما زمن بقائه في الهواء، وهو ليس {1} ث. لذلك حللتُه من السرعة والزاوية وتركتُ {2} ث جانبًا: فهي تخص شيئًا آخر. والحل يبيّن زمن بقائه في الهواء.",
  "The question gives {0} m s⁻¹, but the speed and the angle already decide how fast it lands, and it is not {1} m s⁻¹. So I’ve run it from the speed and the angle and left the {2} m s⁻¹ out: it is about something else. The working shows how fast it lands.": "يذكر السؤال {0} م/ث، لكن السرعة والزاوية تحددان وحدهما سرعة سقوطه، وهي ليست {1} م/ث. لذلك حللتُه من السرعة والزاوية وتركتُ {2} م/ث جانبًا: فهي تخص شيئًا آخر. والحل يبيّن سرعة سقوطه.",
  "No speed was given, so I’ve used {0} m s⁻¹. Tell me the real one and I’ll run it again.": "لم تُذكر سرعة، فاستخدمتُ {0} م/ث. أخبرني بالسرعة الحقيقية وسأعيد الحل.",
  "No angle was given, so it is taken as {0}. Change it on the values screen to try another.": "لم تُذكر زاوية، فنعدّها {0}. غيّرها في شاشة القيم لتجرّب زاوية أخرى.",
