  "dropped|thrown|kicked|launched|fired|flung|hurled|tossed|lobbed|released|projected|catapulted|knocked|pushed|rolled|shot|pitched|let go|nudged|booted|chucked|yeeted": "تُرك|قُذف|رُكل|أُطلق|رُمي|دُفع|دُحرج",
