  "{0} holds its first speed for {1} seconds and then changes speed: the area under its speed–time graph — a rectangle, then a triangle or trapezium{2} — is the distance.": "{0} يثبت على سرعته الأولى مدة {1} ثانية ثم تتغير سرعته: المساحة تحت رسمه البياني للسرعة–الزمن — مستطيل، ثم مثلث أو شبه منحرف{2} — هي المسافة.",
  "{0} changes speed for {1} seconds and then holds its speed: the area under its speed–time graph — a triangle or trapezium while it changes speed, then a rectangle — is the distance.": "{0} تتغير سرعته مدة {1} ثانية ثم يثبت عليها: المساحة تحت رسمه البياني للسرعة–الزمن — مثلث أو شبه منحرف أثناء تغيّر السرعة، ثم مستطيل — هي المسافة.",
