  "Their speeds there are {0} and {1}.": "سرعتاهما هناك {0} و{1}.",
  "Not recommended — frozen. Nothing will move until you drag the time slider yourself.": "غير منصوح به — متجمد. لن يتحرك شيء حتى تسحب شريط الزمن بنفسك.",
  "Not recommended — too fast to follow. The whole flight would be over in {0} s, against {1} s at the speed it asked for.": "غير منصوح به — أسرع من أن تتابعه. ستنتهي الحركة كلها في {0} ث، مقابل {1} ث بالسرعة المناسبة لها.",
  "Not recommended — quicker than this flight wants: {0} s on screen rather than {1} s.": "غير منصوح به — أسرع مما تحتاجه هذه الحركة: {0} ث على الشاشة بدلًا من {1} ث.",
