  "No gravity, so each height is a straight line in {0} and they close at a steady rate.": "بلا جاذبية، فكل ارتفاع خط مستقيم بدلالة {0}، ويتقاربان بمعدل ثابت.",
  "The {0} terms cancel: both fall with the same {1}, so relative to each other neither accelerates, and the gap between them closes at a steady rate. That is why one equation in {2} is enough.": "تُلغى حدود {0}: كلاهما يسقط بـ{1} نفسها، فلا يتسارع أحدهما بالنسبة إلى الآخر، وتتناقص المسافة بينهما بمعدل ثابت. لهذا تكفي معادلة واحدة في {2}.",
