  "where the rock is (or when it would reach it); when it changes course, and its new velocity. Then ask when it is due some direction of the rock, and how far from it at a time.": "وموقع الصخرة (أو متى كانت ستصل إليها)؛ ومتى تغيّر مسارها، وسرعتها الجديدة. ثم اسأل متى تكون في اتجاه ما من الصخرة تمامًا، وكم تبعد عنها عند زمن معين.",
