  "Up the hill and down it": "صعودًا ونزولًا على التل",
  "A car with a steady driving force, against a steady resistance, on a road up a hill. Driven up it, the weight’s component down the slope works against it; driven down it, the same component helps. Give the forces and the road for the speed after a distance — or the speed at the end, and leave a force blank to find it.": "سيارة بقوة دفع ثابتة ضد مقاومة ثابتة، على طريق صاعد على تل. عند الصعود، تعمل مركّبة الوزن على طول المنحدر ضدها؛ وعند النزول، تساعدها المركّبة نفسها. أعطِ القوى والطريق لإيجاد السرعة بعد مسافة، أو السرعة عند النهاية واترك قوة فارغة لإيجادها.",
  "The driving force (N)": "قوة الدفع (نيوتن)",
