  "The resistance to motion (N)": "مقاومة الحركة (نيوتن)",
  "Blank: none — or, with the speed at the end, found.": "فارغة: لا مقاومة، أو تُحسب مع السرعة عند النهاية.",
  "Speed at the start (m s⁻¹)": "السرعة عند البداية (م/ث)",
  "Speed at the end (m s⁻¹)": "السرعة عند النهاية (م/ث)",
