  "brake all the way to the sign; brake to the limit and hold it; react first, then do the same.": "يكبح حتى اللافتة؛ أو يكبح حتى السرعة المحددة ويثبت عليها؛ أو يستجيب أولًا ثم يفعل الشيء نفسه.",
  "The sign": "اللافتة",
