  "its speed at P and its acceleration are found, two equations from P solved together. A third stretch is checked against them.": "فتُحسب سرعتها عند ن وتسارعها، من معادلتين تبدآن من ن تُحلان معًا. ويُقارن مقطع ثالث بالنتيجة للتحقق.",
