  "Two robots on a floor: when are they closest?": "روبوتان على أرضية: متى يكونان أقرب ما يمكن؟",
  "A square floor with centre O, {0} along AB and {1} along AD. Two robots cross it, each at a constant velocity — R’s may come from where it is at two times.": "أرضية مربعة مركزها و، فيها {0} على امتداد أب و{1} على امتداد أد. يعبرها روبوتان، كل منهما بسرعة متجهة ثابتة، وقد تُستخرج سرعة ر من موضعه في زمنين.",
  "A part left blank is 0.": "المركّبة الفارغة تعني 0.",
