  "Light it": "أشعله",
  "The firework rocket": "صاروخ الألعاب النارية",
  "A rocket from rest at ground level is driven straight up with a constant acceleration until it burns out, then moves freely under gravity. Give how long it burns and one thing about the burn; ask its height at a moment after.": "صاروخ يبدأ من السكون عند مستوى الأرض، يدفعه تسارع ثابت رأسيًا إلى أعلى حتى ينفد وقوده، ثم يتحرك بحرية تحت تأثير الجاذبية. اكتب مدة الاحتراق وشيئًا واحدًا عنه؛ واسأل عن ارتفاعه في لحظة لاحقة.",
