  "Above the roof": "فوق السطح",
  "A particle thrown straight up beside a building is above its roof for a time; that time gives the building’s height. Then a second particle thrown up from the roof a moment later: when are they level?": "جسيم يُقذف رأسيًا إلى أعلى بجانب مبنى، فيبقى فوق سطحه مدة من الزمن، ومنها نعرف ارتفاع المبنى. ثم يُقذف جسيم ثانٍ لأعلى من السطح بعد لحظة: متى يتساويان في الارتفاع؟",
  "Thrown up from the ground at (m s⁻¹)": "يُقذف لأعلى من الأرض بسرعة (م/ث)",
