  "Pull": "اسحب",
  "Pulled by a rope": "سحب بحبل",
  "A sledge is pulled over rough snow by a rope — along level ground or up a slope, the rope at an angle to the surface — then let go, and friction brings it to rest. Give its mass, the coefficient of friction, the tension (or its acceleration), and its speed when the rope is let go.": "زلّاجة تُسحب على ثلج خشن بحبل، على أرض مستوية أو صعودًا على منحدر، والحبل يميل بزاوية عن السطح، ثم يُترك الحبل فيوقفها الاحتكاك. اكتب كتلتها ومعامل الاحتكاك والشد (أو تسارعها) وسرعتها عند ترك الحبل.",
  "The tension in the rope (N)": "الشد في الحبل (نيوتن)",
  "Or its acceleration below.": "أو تسارعها في الأسفل.",
