  "Across, each moves at a steady speed, so they are level across at one moment: do they collide, and how high?": "أفقيًا يتحرك كل منهما بسرعة ثابتة، فيتحاذيان أفقيًا في لحظة واحدة: هل يتصادمان، وعلى أي ارتفاع؟",
