  "Two trains leave a station together from rest on parallel tracks and stop together at the next one, each in its own stages. Give what the paper says about each;": "قطاران يغادران محطة معًا من السكون على مسارين متوازيين ويتوقفان معًا عند المحطة التالية، لكل منهما مراحله. اكتب ما تذكره الورقة عن كل منهما؛",
