  "it slides back down": "ينزلق عائدًا لأسفل",
  "it starts there, and only falls from it": "يبدأ من هناك، ولا يفعل بعدها إلا السقوط",
  "it never rises that high: its greatest height is {0}": "لا يصل إلى هذا الارتفاع أبدًا: أقصى ارتفاع له {0}",
