  "arabic english language عربي لغة": "العربية الإنجليزية لغة عربي",
  "Motion is vertical only": "الحركة رأسية فقط",
  "Taking up as positive, {0} at landing": "باعتبار الموجب لأعلى، {0} عند الهبوط",
  "{0}, so there is no vertical acceleration": "{0}، فلا يوجد تسارع رأسي",
  "The object never returns to the ground": "لا يعود الجسم إلى الأرض أبدًا",
  "At the highest point the vertical velocity is zero": "عند أعلى نقطة تكون السرعة الرأسية صفرًا",
  ", each on its own clock. Give where each starts, how fast, and when — the engine finds where they meet, if they do.": "، لكلٍّ منهما ساعته. حدّد من أين يبدأ كلٌّ منهما وبأي سرعة ومتى، والمحرّك يجد أين يلتقيان إن التقيا.",
  "above the ground, at": "فوق الأرض، عند",
  "after B sets off.": "بعد انطلاق ب.",
  "Height of A": "ارتفاع أ",
  "Velocity of A": "سرعة أ",
  "Height of B": "ارتفاع ب",
  "Velocity of B": "سرعة ب",
  "is the height above the ground and": "هو الارتفاع فوق الأرض و",
  "is time on the one clock. B only starts moving at": "هو الزمن على ساعة واحدة. لا يبدأ ب الحركة إلا عند",
  ", so its own time is": "، فزمنه الخاص هو",
  "Negative is downwards. The speeds are": "السالب يعني لأسفل. السرعتان هما",
  ", so they differ by": "، والفرق بينهما",
  "Going down. Up is positive.": "يتجه لأسفل. الموجب لأعلى.",
