  "The one unknown was": "المجهول الوحيد كان",
  "Two side by side, on one straight road or on parallel tracks. Each starts at some speed, may hold it for a while, then changes speed at a steady rate until it reaches a speed it holds — or comes to rest at the line. The engine finds every moment they are level — or, if the paper hides one number, finds it from where they are level.": "اثنان جنبًا إلى جنب، على طريق مستقيم واحد أو على مسارين متوازيين. يبدأ كلٌّ منهما بسرعة ما، وقد يحافظ عليها مدة، ثم يغيّرها بمعدل ثابت حتى يبلغ سرعة يثبت عليها أو يتوقف عند الخط. يجد المحرّك كل لحظة يتحاذيان فيها، وإن أخفت الورقة عددًا واحدًا وجده من موضع تحاذيهما.",
