  ", along the same line from the throw.": "، على الخط نفسه من نقطة القذف.",
  "A velocity–time graph of straight segments: each one from the velocity it starts at to the one it ends at, over its own time. Below zero is going back. Leave a moving segment’s time blank and say where it ends; leave a stop’s time blank and give the total time.": "رسم بياني للسرعة–الزمن من قطع مستقيمة: كل قطعة من السرعة التي تبدأ بها إلى التي تنتهي بها، خلال زمنها. وما تحت الصفر يعني العودة. اترك زمن قطعة متحركة فارغًا واذكر أين تنتهي؛ واترك زمن توقف فارغًا وأعطِ الزمن الكلي.",
  "On foot, the driver covers": "مشيًا، يقطع السائق",
