  "is the one quantity not given, so everything that depends on it is written in terms of it, and one equation is left to find it. Each stage that changes speed is": "هو الكمية الوحيدة غير المعطاة، فيُكتب كل ما يعتمد عليها بدلالتها، وتبقى معادلة واحدة لإيجادها. كل مرحلة تتغير فيها السرعة هي",
  "Each stage is one piece of the area: a rectangle where the speed holds,": "كل مرحلة قطعة من المساحة: مستطيل حيث تثبت السرعة،",
  "; a trapezium where it changes,": "؛ وشبه منحرف حيث تتغير،",
  "— a triangle when it starts or ends at rest. Together they are the whole distance.": "— ومثلث عندما تبدأ أو تنتهي من السكون. ومعًا تعطي المسافة كلها.",
  "is negative, and a speed cannot be, so it is rejected.": "سالبة، والسرعة لا تكون سالبة، فتُرفض.",
  "Model {0}: The whole drive to the sign": "النموذج {0}: الرحلة كلها حتى اللافتة",
