  "strip lower": "الشريط أخفض",
  "A motion along one line in stages, one after another, each with its own constant acceleration. For each stage give any three of what the paper says — the speed it ends at is the speed the next one starts at. A stage short of one number can take it from the whole distance or the whole time.": "حركة على خط واحد على مراحل متتالية، لكلٍّ منها تسارع ثابت خاص بها. لكل مرحلة أعطِ أي ثلاثة مما تقوله الورقة؛ والسرعة التي تنتهي بها مرحلة هي التي تبدأ بها التالية. والمرحلة التي ينقصها عدد واحد يمكن أن تأخذه من المسافة الكلية أو الزمن الكلي.",
  "Two particles on a horizontal surface, each with its own constant acceleration, all in": "جسيمان على سطح أفقي، لكلٍّ منهما تسارع ثابت خاص به، وكل شيء بدلالة",
