  "north — known from two moments: its velocity at two times, or where it starts and where it is later. Its acceleration may change at the second moment. Leave the acceleration blank to have it found.": "شمالًا، يُعرف من لحظتين: سرعته في زمنين، أو من أين يبدأ وأين يكون لاحقًا. وقد يتغير تسارعه عند اللحظة الثانية. اترك التسارع فارغًا ليجده المحرّك.",
