  "A ball falls freely past M and then N below it — the top and bottom of a window, or two marks on a cliff. Give two of the speed at M, the speed at N, the time between and the distance between, or work in letters: the speed at N a multiple of": "تسقط كرة سقوطًا حرًا مارّة بـ م ثم بـ ن تحتها، كأعلى نافذة وأسفلها، أو علامتين على جرف. أعطِ اثنين مما يلي: السرعة عند م، والسرعة عند ن، والزمن بينهما، والمسافة بينهما، أو اعمل بالرموز: السرعة عند ن مضاعف لـ",
