  "{0} · Steady descent — from": "{0} · هبوط بسرعة ثابتة، من",
  "This is the phase she is in now. Constant velocity: the two forces are equal and opposite, which is what terminal velocity means.": "هذه هي المرحلة التي هي فيها الآن. سرعة ثابتة: القوتان متساويتان ومتعاكستان، وهذا معنى السرعة الحدّية.",
