  "Edexcel {0}MA{1}/{2} Jun {3} Q{4} · WJEC {5}U{6}{7} Unit {8} Jun {9} Q{10} · AQA MM{11}B Jan {12} Q{13} · Edexcel {14}MA{15}/{16} Jun {17} Q{18} · WJEC {19}U{20}{21} Unit {22} Jun {23} Q{24} · OCR MEI H{25}/{26} Jun {27} Q{28} · WJEC {29}U{30}{31} Unit {32} Jun {33} Q{34}": "إدكسل {0} إم إيه {1}/{2} يونيو {3} سؤال {4} · دبليو جيه إي سي {5} يو {6}{7} الوحدة {8} يونيو {9} سؤال {10} · إيه كيو إيه إم إم{11} بي يناير {12} سؤال {13} · إدكسل {14} إم إيه {15}/{16} يونيو {17} سؤال {18} · دبليو جيه إي سي {19} يو {20}{21} الوحدة {22} يونيو {23} سؤال {24} · أو سي آر إم إي آي إتش{25}/{26} يونيو {27} سؤال {28} · دبليو جيه إي سي {29} يو {30}{31} الوحدة {32} يونيو {33} سؤال {34}",
  "Edexcel {0}/{1} M{2} Jun {3} Q{4} · Edexcel {5}/{6} M{7} Jun {8} Q{9}": "إدكسل {0}/{1} إم{2} يونيو {3} سؤال {4} · إدكسل {5}/{6} إم{7} يونيو {8} سؤال {9}",
