  "CIE {0}/{1} specimen for {2} Q{3} · Edexcel {4} M{5} Nov {6} Q{7}": "سي آي إي {0}/{1} نموذج تجريبي لعام {2} سؤال {3} · إدكسل {4} إم{5} نوفمبر {6} سؤال {7}",
  "Edexcel {0} M{1} Nov {2} Q{3} · Edexcel {4}/{5} M{6} Jun {7} Q{8} · Edexcel {9} M{10} Jan {11} Q{12}": "إدكسل {0} إم{1} نوفمبر {2} سؤال {3} · إدكسل {4}/{5} إم{6} يونيو {7} سؤال {8} · إدكسل {9} إم{10} يناير {11} سؤال {12}",
  "OCR {0} M{1} Jan {2} Q{3}": "أو سي آر {0} إم{1} يناير {2} سؤال {3}",
