  "{0} · The canopy opens — from {1}": "{0} · فتح المظلة — من {1}",
  "{0} · Steady descent — from {1}": "{0} · هبوط منتظم — من {1}",
  "Downwards is positive here, and the time is measured from the start of this phase — free fall, which began at {0}.": "الاتجاه لأسفل موجب هنا، والزمن يُقاس من بداية هذه المرحلة — السقوط الحر، التي بدأت عند {0}.",
  "Downwards is positive here, and the time is measured from the start of this phase — the canopy opens, which began at {0}.": "الاتجاه لأسفل موجب هنا، والزمن يُقاس من بداية هذه المرحلة — فتح المظلة، التي بدأت عند {0}.",
  "She reaches the ground before the canopy has finished slowing her, so she lands at {0} rather than at the {1} you asked for. Open it earlier, or give it a harder deceleration.": "تصل إلى الأرض قبل أن تُنهي المظلة إبطاءها، ولذلك تهبط بسرعة {0} بدلًا من {1} التي طلبتها. افتحها أبكر، أو أعطها تباطؤًا أشد.",
  "After {0} of free fall she is doing {1}, which is already at or below the {2} you have given as the steady speed — so the canopy has nothing to slow down. Open it later, or give a slower steady speed.": "بعد {0} من السقوط الحر تكون سرعتها {1}، وهي بالفعل عند {2} التي حددتها كسرعة ثابتة أو أقل منها — فلا شيء تبطئه المظلة. افتحها لاحقًا، أو حدد سرعة ثابتة أبطأ.",
  "Still needed: the gravitational field — pick one below, how long she falls before the canopy opens, the deceleration the canopy gives and the steady speed she settles to.": "ما زال مطلوبًا: مجال الجاذبية — اختر واحدًا أدناه، ومدة سقوطها قبل فتح المظلة، والتباطؤ الذي تعطيه المظلة، والسرعة الثابتة التي تستقر عليها.",
  "A test.": "اختبار.",
  "Ignore air resistance. Use v² = u² + {0}as and take a = {1}.": "أهمل مقاومة الهواء. استخدم ع² = ع₀² + {0} ت ف وخذ ت = {1}.",
  "it lands on the ground {0} below the launch point, so {1} · {2} → {3} · {4} → {5}": "يهبط على الأرض على بعد {0} أسفل نقطة القذف، إذن {1} · {2} ← {3} · {4} ← {5}",
  "it lands back at the level it was launched from, so {0} · {1} → {2} · {3} → {4}": "يهبط عائدًا إلى مستوى قذفه، إذن {0} · {1} ← {2} · {3} ← {4}",
  "canopy": "المظلة",
