  "A car off a cliff Composed by Ask Suvat from the app’s own pieces: a cliff, a car, launched, then falling freely. Change any number and the engine works it out again.": "سيارة من فوق جرف ركّبه اسأل سوفات من قطع التطبيق نفسه: جرف، سيارة، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
  "A cyclist off a bridge Composed by Ask Suvat from the app’s own pieces: a bridge, a cyclist, launched, then falling freely. Change any number and the engine works it out again.": "راكب دراجة من فوق جسر ركّبه اسأل سوفات من قطع التطبيق نفسه: جسر، راكب دراجة، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
