  "The cyclist is a particle": "راكب الدراجة جسيم",
  "A ball off a house Composed by Ask Suvat from the app’s own pieces: a house and a fence, a ball, launched, then falling freely. Change any number and the engine works it out again.": "كرة من فوق بيت ركّبه اسأل سوفات من قطع التطبيق نفسه: بيت وسور، كرة، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
