  "The motorcycle is a particle": "الدراجة النارية جسيم",
  "A ball thrown over the open sea Composed by Ask Suvat from the app’s own pieces: the open sea, a ball, launched, then falling freely. Change any number and the engine works it out again.": "كرة تُقذف فوق عرض البحر ركّبه اسأل سوفات من قطع التطبيق نفسه: عرض البحر، كرة، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
  "A ball thrown in a sports hall Composed by Ask Suvat from the app’s own pieces: a sports hall, a ball, launched, then falling freely. Change any number and the engine works it out again.": "كرة تُقذف في صالة رياضية ركّبه اسأل سوفات من قطع التطبيق نفسه: صالة رياضية، كرة، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
  "A ball falling from a tree Composed by Ask Suvat from the app’s own pieces: an orchard, a ball, launched, then falling freely. Change any number and the engine works it out again.": "كرة تسقط من شجرة ركّبه اسأل سوفات من قطع التطبيق نفسه: بستان، كرة، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
  "the ball hits the ground {0} below where it was thrown from, so {1}": "تصطدم الكرة بالأرض على بعد {0} أسفل نقطة قذفها، إذن {1}",
  "A stone off a tower Composed by Ask Suvat from the app’s own pieces: a tower, a stone, launched, then falling freely. Change any number and the engine works it out again.": "حجر من فوق برج ركّبه اسأل سوفات من قطع التطبيق نفسه: برج، حجر، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
  "The stone hits the ground at the foot of the tower at {0}, at {1}.": "يصطدم الحجر بالأرض عند أسفل البرج عند {0}، بسرعة {1}.",
  "The stone is a particle": "الحجر جسيم",
  "A person off a diving board Composed by Ask Suvat from the app’s own pieces: a diving board, a person, launched, then falling freely. Change any number and the engine works it out again.": "شخص من فوق لوح غطس ركّبه اسأل سوفات من قطع التطبيق نفسه: لوح غطس، شخص، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
  "the person enters the water {0} below where they started, so {1}": "يدخل الشخص الماء على بعد {0} أسفل نقطة بدايته، إذن {1}",
  "The person enters the water below the end of the board at {0}, at {1}.": "يدخل الشخص الماء تحت طرف اللوح عند {0}، بسرعة {1}.",
  "Launched above the water, so longer coming down than going up.": "قُذف من فوق الماء، فنزوله أطول من صعوده.",
  "A ball off a cliff Composed by Ask Suvat from the app’s own pieces: a cliff, a ball, launched, then falling freely. Change any number and the engine works it out again.": "كرة من فوق جرف ركّبه اسأل سوفات من قطع التطبيق نفسه: جرف، كرة، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
