  "A coin off a table Composed by Ask Suvat from the app’s own pieces: a table, a coin, launched, then falling freely. Change any number and the engine works it out again.": "عملة من فوق طاولة ركّبه اسأل سوفات من قطع التطبيق نفسه: طاولة، عملة، انطلاق ثم سقوط حر. غيّر أي عدد ويحسبه المحرّك من جديد.",
