  "the bucket hits the water {0} below where it started, so {1}": "يصطدم الدلو بالماء على بعد {0} أسفل نقطة بدايته، إذن {1}",
  "The bucket hits the water at the bottom of the well at {0}, at {1}.": "يصطدم الدلو بالماء عند قاع البئر عند {0}، بسرعة {1}.",
