  "The stone, timed from when it sets off at {0}: Resolve the initial velocity": "الحجر، محسوبًا من لحظة انطلاقه عند {0}: حلّل السرعة الابتدائية",
  "The stone, timed from when it sets off at {0}: Time of flight — vertical, {1}": "الحجر، محسوبًا من لحظة انطلاقه عند {0}: زمن الطيران: رأسيًا، {1}",
