  "The first ball: It rises to {0} above the ground, {1} above where it was thrown from, at {2}.": "الكرة الأولى: ترتفع إلى {0} فوق الأرض، {1} فوق نقطة قذفها، عند {2}.",
  "The first ball: It hits the ground {0} out from the tower at {1}, at {2}.": "الكرة الأولى: تصطدم بالأرض على بعد {0} من البرج عند {1}، بسرعة {2}.",
  "The second ball: It rises to {0} above the ground, {1} above where it was thrown from, at {2}.": "الكرة الثانية: ترتفع إلى {0} فوق الأرض، {1} فوق نقطة قذفها، عند {2}.",
  "The second ball: It hits the ground {0} out from the tower at {1}, at {2}.": "الكرة الثانية: تصطدم بالأرض على بعد {0} من البرج عند {1}، بسرعة {2}.",
