  "The first ball lands first, {0} before the second ball. They land {1} apart.": "تهبط الكرة الأولى أولًا، قبل الكرة الثانية بـ {0}. وتهبطان على بعد {1} إحداهما من الأخرى.",
  "The first ball lands at {0}, {1} out; the second ball at {2}, {3} out.": "تهبط الكرة الأولى عند {0}، على بعد {1}؛ والكرة الثانية عند {2}، على بعد {3}.",
  "The first ball and the second ball are particles": "الكرة الأولى والكرة الثانية جسيمان",
  "A ball bouncing by a house Composed by Ask Suvat from the app’s own pieces: a house and a fence, a ball, a ball that bounces. Change any number and the engine works it out again.": "كرة ترتد بجانب بيت ركّبه اسأل سوفات من قطع التطبيق نفسه: بيت وسور، كرة، كرة ترتد. غيّر أي عدد ويحسبه المحرّك من جديد.",
  "A ball bouncing in a sports hall Composed by Ask Suvat from the app’s own pieces: a sports hall, a ball, a ball that bounces. Change any number and the engine works it out again.": "كرة ترتد في صالة رياضية ركّبه اسأل سوفات من قطع التطبيق نفسه: صالة رياضية، كرة، كرة ترتد. غيّر أي عدد ويحسبه المحرّك من جديد.",
  "There is no backdrop called “atlantis”. The backdrops are: cliff, tower, bridge, house, ground, sea, road, rails, orchard, hall, board, table, well, mountain, forest, harbour, city, moon, snow, desert, pier, site, mars, canyon, waterfall, lighthouse, highjump, rugby, pitch, golf, stadium, ship, dam, playground, beach, room, planet, court, arena, castle, runway, garden, farm, cricket, lake, island, skatepark, circus, polar, oilrig, treehouse, fairground, carpark, volcano, mineshaft, quarry, air.": "لا توجد خلفية اسمها «أتلانتس». الخلفيات هي: جرف، برج، جسر، بيت، أرض، بحر، طريق، قضبان، بستان، صالة، لوح غطس، طاولة، بئر، جبل، غابة، ميناء، مدينة، قمر، ثلج، صحراء، رصيف بحري، موقع بناء، المريخ، وادٍ، شلال، منارة، وثب عالٍ، رجبي، ملعب، جولف، استاد، سفينة، سد، ملعب أطفال، شاطئ، غرفة، كوكب، ملعب مغلق، حلبة، قلعة، مدرج طائرات، حديقة، مزرعة، كريكيت، بحيرة، جزيرة، ساحة تزلج، سيرك، قطبي، منصة نفط، بيت شجرة، مدينة ملاهٍ، موقف سيارات، بركان، منجم، محجر، جو.",
  "There is no engine called “warp”. The engines are: projectile, twin, stages, overtake, pair, bounce, plane.": "لا يوجد محرّك اسمه «وارب». المحرّكات هي: مقذوف، توأم، مراحل، تجاوز، زوج، ارتداد، مستوى.",
  "The scene was given a value launched, then falling freely does not use (mass). It uses the height, the speed, the angle, the landing speed, the distance out, the time in the air, the time to the top, a height asked about, g.": "أُعطي المشهد قيمة لا يستخدمها «انطلاق ثم سقوط حر» (الكتلة). فهو يستخدم الارتفاع، والسرعة، والزاوية، وسرعة الهبوط، والمسافة الأفقية، وزمن الطيران، والزمن حتى القمة، وارتفاعًا مسؤولًا عنه، و جـ.",
  "From a tree only an apple, a ball, a stone, a particle, a bird or a squirrel can fall: not a car.": "من الشجرة لا يسقط إلا تفاحة أو كرة أو حجر أو جسيم أو طائر أو سنجاب: لا سيارة.",
