  // ── A catch on the boundary (boundary-catch): the scenario, its kit, its engine and its stage
  "A catch on the boundary": "إمساك الكرة عند حدّ الملعب",
  "a cricket ball struck towards the rope — is it low enough there for the fielder to catch?": "كرة كريكيت تُضرب نحو حبل الحدّ — هل تصل إليه منخفضة بما يكفي ليمسكها لاعب الميدان؟",
  "A batter strikes a cricket ball at a speed and an angle; a fielder stands on the boundary some distance away and can catch it only if it arrives less than a height above the point it was struck from. Across, its speed never changes, so the distance gives the time to the boundary; up, s = ut + ½at² then gives its height there. Under the reach it is caught; at or over it, it carries the fielder; back down to that height before the boundary, it never reaches them on the full. Then its greatest height, where it would come down, and its momentum p = mv just after the hit.": "يضرب الضارب كرة كريكيت بسرعة وزاوية معيّنتين؛ ويقف لاعب الميدان على حدّ الملعب على بُعد ما منه، ولا يستطيع إمساكها إلا إذا وصلت إليه على ارتفاع أقل من حدّ معيّن فوق النقطة التي ضُربت منها. أفقيًا لا تتغيّر سرعتها، فتعطي المسافةُ زمنَ الوصول إلى الحدّ؛ ورأسيًا تعطي ف = ع₀ ز + ½ ت ز² ارتفاعها هناك. إن كانت تحت حدّ الإمساك أُمسكت؛ وإن ساوته أو زادت عليه تجاوزت اللاعب؛ وإن عادت إلى ذلك الارتفاع قبل الحدّ فلن تصل إليه قبل أن تلمس الأرض. ثم أقصى ارتفاع لها، وأين كانت ستهبط، وكمية حركتها غ = ك ع بعد الضربة مباشرة.",
  "A catch on the boundary a cricket ball struck towards the rope — is it low enough there for the fielder to catch? A batter strikes a cricket ball at a speed and an angle; a fielder stands on the boundary some distance away and can catch it only if it arrives less than a height above the point it was struck from. Across, its speed never changes, so the distance gives the time to the boundary; up, s = ut + ½at² then gives its height there. Under the reach it is caught; at or over it, it carries the fielder; back down to that height before the boundary, it never reaches them on the full. Then its greatest height, where it would come down, and its momentum p = mv just after the hit.": "إمساك الكرة عند حدّ الملعب كرة كريكيت تُضرب نحو حبل الحدّ — هل تصل إليه منخفضة بما يكفي ليمسكها لاعب الميدان؟ يضرب الضارب كرة كريكيت بسرعة وزاوية معيّنتين؛ ويقف لاعب الميدان على حدّ الملعب على بُعد ما منه، ولا يستطيع إمساكها إلا إذا وصلت إليه على ارتفاع أقل من حدّ معيّن فوق النقطة التي ضُربت منها. أفقيًا لا تتغيّر سرعتها، فتعطي المسافةُ زمنَ الوصول إلى الحدّ؛ ورأسيًا تعطي ف = ع₀ ز + ½ ت ز² ارتفاعها هناك. إن كانت تحت حدّ الإمساك أُمسكت؛ وإن ساوته أو زادت عليه تجاوزت اللاعب؛ وإن عادت إلى ذلك الارتفاع قبل الحدّ فلن تصل إليه قبل أن تلمس الأرض. ثم أقصى ارتفاع لها، وأين كانت ستهبط، وكمية حركتها غ = ك ع بعد الضربة مباشرة.",
